<script>
 import {csvCell,targetExportSVG} from '#lib/utils/activity-export.js';
 import {lang} from '#lib/stores/lang.js';
 import {activityLabel} from '#lib/utils/activity-labels.js';
 import {targetPoint,targetStats,completeResponse} from '#lib/utils/target-state.js';
 import {useUnsavedChanges} from '#lib/utils/unsaved.js';
 let presetKey='reflection',lastLanguage='ru';
 let mode='setup',topics=[],title='',responseMode='complete',responses=[],draft={},submitted=false,people=0,quickTopic=0,past=[],future=[],message='',dirty=false,targetSvg;
 $: ui=key=>activityLabel($lang,key);
 $: levels=ui('levels').split('|');
 $: if(!topics.length)topics=ui('reflectionTopics').split('|');
 $: if(lastLanguage!==$lang){if(topics.join('|')===activityLabel(lastLanguage,presetKey+'Topics'))topics=ui(presetKey+'Topics').split('|');lastLanguage=$lang;}
 $: stats=targetStats(responses,topics.length);
 $: answered=completeResponse(draft,topics.length).length;
 $: points=mode==='collect'&&responseMode==='complete'?completeResponse(draft,topics.length):responses;
 const colors=['#8b68ce','#de83a9','#52a398','#cf9b50','#638ccc','#be7898','#7c9c4f','#a87cb6'];
 useUnsavedChanges(()=>dirty,()=>$lang);
 function snapshot(){return structuredClone({mode,topics,title,responseMode,responses,people,draft,submitted});}
 function restore(s){({mode,topics,title,responseMode,responses,people,draft,submitted}=s);dirty=true;quickTopic=0;}
 function remember(){past=[...past.slice(-39),snapshot()];future=[];dirty=true;}
 function undo(){if(!past.length)return;future=[snapshot(),...future];const s=past.at(-1);past=past.slice(0,-1);restore(s);}
 function redo(){if(!future.length)return;past=[...past,snapshot()];const s=future[0];future=future.slice(1);restore(s);}
 function preset(key){presetKey=key;topics=ui(key+'Topics').split('|');dirty=true;}
 function start(){if(topics.some(t=>!t.trim())){message=ui('invalidTopics');return;}remember();topics=topics.map(t=>t.trim());mode='collect';message='';draft={};submitted=false;}
 function vote(sector,level){if(submitted)return;if(responseMode==='complete'){draft={...draft,[sector]:level};dirty=true;}else{remember();responses=[...responses,{sector,level}];}}
 function tap(event){if(mode!=='collect'||responseMode!=='quick')return;const box=event.currentTarget.getBoundingClientRect();const hit=targetPoint((event.clientX-box.left)/box.width*400,(event.clientY-box.top)/box.height*400,topics.length);if(hit)vote(hit.sector,hit.level);}
 function submit(){if(submitted||answered!==topics.length)return;remember();responses=[...responses,...completeResponse(draft,topics.length)];people++;submitted=true;}
 function next(){draft={};submitted=false;}
 function edit(){remember();mode='setup';responses=[];people=0;draft={};submitted=false;}
 function point(sector,level,index=0){const angle=-Math.PI/2+(sector+.5)*Math.PI*2/topics.length+(index%5-2)*.035;const radius=170*(1-(level+.5)/3);return {x:200+Math.cos(angle)*radius,y:200+Math.sin(angle)*radius};}
 function wedge(index){const start=-Math.PI/2+index*Math.PI*2/topics.length,end=start+Math.PI*2/topics.length;return `M200 200 L${200+170*Math.cos(start)} ${200+170*Math.sin(start)} A170 170 0 0 1 ${200+170*Math.cos(end)} ${200+170*Math.sin(end)} Z`;}
 function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function csv(){const rows=[[ui('lesson'),title],[ui('topic'),ui('marks'),...levels],...topics.map((topic,i)=>[topic,stats.topics[i].count,...stats.topics[i].distribution])];download('\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8','evrika-reflection.csv');dirty=!submitted&&answered>0;}
 function svg(){const source=new XMLSerializer().serializeToString(targetSvg);download(targetExportSVG(source,title||ui('target'),topics,levels,ui('scale')),'image/svg+xml','evrika-target.svg');}

</script>
<div class="reflection">
 <header><div><span class="eyebrow">EVRIKA LAB · 02</span><h1>{ui('target')}</h1><p>{ui('targetHint')}</p></div><span class="mode-chip">{ui(mode==='setup'?'setup':mode==='collect'?'collect':'results')}</span></header>
 <p class="privacy">{ui('privacy')}</p>
 {#if mode==='setup'}
 <div class="setup-grid"><section class="panel"><h2>{ui('setup')}</h2><label>{ui('lesson')}<input maxlength="100" bind:value={title} on:input={()=>dirty=true}/></label><h3>{ui('presets')}</h3><div class="presets">{#each ['reflection','knowledge','feelings'] as key}<button on:click={()=>preset(key)}>{ui(key)}</button>{/each}</div><h3>{ui('topics')}</h3>
 {#each topics as topic,i}<div class="topic-row"><span style={`background:${colors[i]}`}>{i+1}</span><input aria-label={`${ui('topic')} ${i+1}`} maxlength="70" bind:value={topics[i]} on:input={()=>dirty=true}/><button aria-label={`${ui('remove')} ${ui('topic')} ${i+1}`} disabled={topics.length<=2} on:click={()=>{topics=topics.filter((_,j)=>j!==i);dirty=true;}}>×</button></div>{/each}
 <button class="add" disabled={topics.length>=8} on:click={()=>{topics=[...topics,''];dirty=true;}}>＋ {ui('addTopic')}</button><h3>{ui('responseMode')}</h3><div class="mode-options">{#each ['complete','quick'] as value}<button class:active={responseMode===value} aria-pressed={responseMode===value} on:click={()=>{responseMode=value;dirty=true;}}>{ui(value)}</button>{/each}</div><p class="hint">{ui(responseMode+'Hint')}</p><button class="primary wide" on:click={start}>{ui('start')} →</button>
 {#if past.length}<button class="wide" on:click={undo}>↶ {ui('undo')}</button>{/if}
 </section><section class="visual-panel"><div class="target-wrap"><svg viewBox="0 0 400 400" role="img" aria-label={ui('target')}><circle cx="200" cy="200" r="187" fill="#ffffff50"/>{#each topics as topic,i}<path d={wedge(i)} fill={colors[i]} opacity=".48" stroke="white" stroke-width="2"/>{@const p=point(i,0)}<text x={p.x} y={p.y+5} text-anchor="middle" fill="#493659" font-size="17" font-weight="700">{i+1}</text>{/each}<circle cx="200" cy="200" r="113.33" fill="#ffffff35" stroke="#ffffff" stroke-width="2"/><circle cx="200" cy="200" r="56.67" fill="#ffffff80" stroke="#ffffff" stroke-width="2"/><circle cx="200" cy="200" r="6" fill="#ffffff"/></svg></div><h3>{ui('scale')}</h3><ol class="scale">{#each levels as level,i}<li><span>{i===0?'○':i===1?'◉':'●'}</span>{level}</li>{/each}</ol><p class="honesty">{ui('honesty')}</p></section></div>
 {:else}
 <div class="session-bar"><div><h2>{title||ui('target')}</h2><p role="status" aria-live="polite"><b>{responseMode==='complete'?people:stats.total}</b> {ui(responseMode==='complete'?'responses':'marks')}</p></div><div class="session-actions"><button disabled={!past.length} on:click={undo}>↶ {ui('undo')}</button><button disabled={!future.length} on:click={redo}>↷ {ui('redo')}</button><button on:click={()=>mode=mode==='stats'?'collect':'stats'}>{ui(mode==='stats'?'back':'results')}</button></div></div>
 <div class="session-grid" class:content-first={responseMode==='complete'||mode==='stats'}><section class="visual-panel"><div class="target-wrap"><!-- The same voting action is available through the labeled buttons below. -->
<!-- svelte-ignore a11y-click-events-have-key-events a11y-no-noninteractive-element-interactions -->
<svg bind:this={targetSvg} viewBox="0 0 400 400" role="img" aria-label={ui('target')} on:click={tap}><circle cx="200" cy="200" r="187" fill="#ffffff50"/>{#each topics as topic,i}<path d={wedge(i)} fill={colors[i]} opacity=".48" stroke="white" stroke-width="2"/>{@const p=point(i,0)}<text x={p.x} y={p.y+5} text-anchor="middle" fill="#493659" font-size="17" font-weight="700">{i+1}</text>{/each}<circle cx="200" cy="200" r="113.33" fill="#ffffff35" stroke="#ffffff" stroke-width="2"/><circle cx="200" cy="200" r="56.67" fill="#ffffff80" stroke="#ffffff" stroke-width="2"/>{#each points as p,i}{@const xy=point(p.sector,p.level,i)}<circle cx={xy.x} cy={xy.y} r="5" fill="#493359" stroke="white" stroke-width="1.5"/>{/each}<circle cx="200" cy="200" r="5" fill="white"/></svg></div><div class="legend">{#each topics as topic,i}<div><b style={`background:${colors[i]}`}>{i+1}</b><span>{topic}</span></div>{/each}</div><ol class="scale">{#each levels as level,i}<li><span>{i===0?'○':i===1?'◉':'●'}</span>{level}</li>{/each}</ol></section>
 <section class="panel">
 {#if mode==='collect'}
  {#if submitted}<div class="thanks" role="status"><span>✓</span><h2>{ui('thanks')}</h2><button class="primary" on:click={next}>{ui('nextStudent')} →</button></div>
  {:else}<h2>{ui('collect')}</h2><p class="hint">{ui(responseMode==='complete'?'targetTap':'quickTap')}</p>
   {#if responseMode==='complete'}<div class="progress"><span>{ui('progress')} {answered}/{topics.length}</span><div style={`--progress:${answered/topics.length*100}%`}></div></div>
    {#each topics as topic,i}<fieldset><legend><span style={`background:${colors[i]}`}>{i+1}</span>{topic}</legend><div class="choices">{#each levels as label,level}<button class:checked={draft[i]===level} aria-pressed={draft[i]===level} on:click={()=>vote(i,level)}>{label}</button>{/each}</div></fieldset>{/each}<button class="primary wide" disabled={answered!==topics.length} on:click={submit}>{ui('submit')} →</button>
   {:else}<label>{ui('quickTopic')}<select bind:value={quickTopic}>{#each topics as topic,i}<option value={i}>{i+1}. {topic}</option>{/each}</select></label><div class="quick-choices">{#each levels as label,level}<button on:click={()=>vote(Number(quickTopic),level)}>{label} ＋</button>{/each}</div><p class="honesty">{ui('quickHint')}</p>{/if}
  {/if}
 {:else}<h2>{ui('results')}</h2><div class="metrics"><div><b>{stats.total}</b><span>{ui('marks')}</span></div><div><b>{stats.covered}/{topics.length}</b><span>{ui('coverage')}</span></div></div>
  {#if !stats.total}<p class="hint">{ui('noData')}</p>{:else}{#each topics as topic,i}{@const data=stats.topics[i]}<div class="result"><h3><span style={`background:${colors[i]}`}>{i+1}</span>{topic}</h3><div class="distribution">{#each data.distribution as n,j}<div style={`width:${data.count?n/data.count*100:0}%;background:${['#d291a3','#d6b477','#78a99a'][j]}`} title={`${levels[j]}: ${n}`}></div>{/each}</div><ul>{#each levels as label,j}<li><span>{label}</span><b>{data.distribution[j]}</b></li>{/each}</ul>{#if !data.count}<p class="hint">{ui('noData')}</p>{:else if data.distribution[0]>0}<p class="support">{ui('support')}: {data.distribution[0]}</p>{/if}</div>{/each}{/if}
  {#if stats.covered<topics.length}<p class="hint">{ui('missing')}</p>{/if}<p class="honesty">{ui('honesty')}</p><button class="wide" disabled={!stats.total} on:click={csv}>{ui('export')}</button><button class="wide" on:click={svg}>{ui('svg')}</button>
 {/if}
 </section></div><footer><p>{ui('resetHint')}</p><button on:click={edit}>{ui('edit')}</button></footer>
 {/if}
 {#if message}<p role="alert">{message}</p>{/if}
</div>
<style>
 .reflection{color:#453351;}header{display:flex;justify-content:space-between;align-items:center;gap:20px;}.eyebrow{font-size:10px;font-weight:800;letter-spacing:2px;color:#695182;}h1{font-size:30px;font-weight:750;line-height:1.2;margin:8px 0;}header p{font-size:14px;max-width:650px;line-height:1.7;color:#69577d;}.mode-chip{background:#ffffffa0;border:1px solid white;padding:10px 18px;border-radius:30px;font-size:11px;white-space:nowrap;}.privacy{font-size:11px;color:#725b85;margin:16px 0 24px;}.setup-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:24px;}.panel,.visual-panel{min-width:0;border:1px solid #fff;border-radius:24px;padding:26px;background:#ffffffdb;}.visual-panel{background:#ffffff60;display:flex;flex-direction:column;justify-content:center;}h2{font-size:20px;font-weight:700;}h3{font-size:12px;font-weight:650;margin:20px 0 12px;}button{min-height:44px;min-width:44px;padding:10px 14px;border-radius:11px;border:1px solid #dfd2eb;background:#fff;color:#675078;font-size:12px;line-height:1.4;}button:hover{background:#f2eafb;}button:disabled{opacity:.4;cursor:default;}button.primary{background:var(--color-primary);color:#fff;border-color:var(--color-primary);margin-top:16px;font-weight:650;}.wide{width:100%;margin-top:8px;}label{display:flex;flex-direction:column;gap:7px;font-size:12px;margin:18px 0;}input,select{width:100%;min-width:0;background:#fff;border:1px solid #ded5e9;border-radius:10px;padding:11px;font-size:14px;color:#453251;}.presets{display:flex;gap:6px;flex-wrap:wrap;}.presets button{font-size:11px;}.topic-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;}.topic-row>span{width:25px;height:25px;flex-shrink:0;border-radius:50%;font-size:11px;color:#fff;display:grid;place-items:center;}.topic-row button{padding:5px;}.add{width:100%;border-style:dashed;}.mode-options{display:flex;gap:8px;}.mode-options button{flex:1;}.mode-options .active{border-color:#8d65ba;background:#eee3fb;}.hint{font-size:12px;line-height:1.7;color:#897295;margin:12px 0;}.target-wrap{width:100%;max-width:470px;margin:0 auto;}svg{width:100%;height:auto;touch-action:manipulation;}.scale{display:flex;flex-direction:column;gap:9px;margin:16px 0;font-size:12px;color:#715c81;}.scale span{margin-right:10px;color:#7a559f;font-size:17px;}.honesty{background:#ffffff90;border-left:3px solid #a98ac6;border-radius:6px;padding:14px;font-size:11px;color:#887194;line-height:1.7;margin:18px 0;}.session-bar{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:18px;background:#ffffffb0;padding:18px 22px;border-radius:18px;}.session-bar p{font-size:12px;color:#8d729d;margin-top:5px;}.session-bar p b{color:#62417d;}.session-actions{display:flex;gap:7px;flex-wrap:wrap;}.session-grid{display:grid;grid-template-columns:1fr 1.15fr;gap:20px;align-items:start;}.legend{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11px;}.legend>div{display:flex;gap:8px;align-items:center;overflow-wrap:anywhere;}.legend b,legend span,.result h3 span{width:22px;height:22px;border-radius:50%;display:inline-grid;place-items:center;color:white;font-size:10px;flex-shrink:0;}.progress{font-size:10px;color:#9473a4;margin:18px 0;}.progress>div{height:5px;border-radius:8px;background:linear-gradient(to right,#9970c5 var(--progress),#eee6f3 var(--progress));margin-top:8px;}fieldset{margin:20px 0;min-width:0;}legend{display:flex;align-items:center;gap:9px;font-size:13px;font-weight:600;margin-bottom:10px;overflow-wrap:anywhere;}.choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;}.choices button{font-size:11px;padding:10px 8px;min-height:58px;}.choices .checked{background:#7350ad;border-color:#7350ad;color:white;box-shadow:0 3px 9px #7350ad22;}.quick-choices{display:flex;flex-direction:column;gap:9px;}.thanks{text-align:center;padding:35px 10px;}.thanks>span{display:grid;place-items:center;width:64px;height:64px;background:#e2f3e8;color:#4c9469;border-radius:50%;font-size:32px;margin:0 auto 20px;}.thanks h2{font-size:21px;line-height:1.5;}.metrics{display:flex;gap:12px;margin:18px 0;}.metrics>div{flex:1;background:#f3edf8;border-radius:12px;padding:16px;}.metrics b{display:block;font-size:28px;}.metrics span{font-size:10px;color:#957ba4;}.distribution{display:flex;height:9px;background:#eee7f2;border-radius:7px;overflow:hidden;}.result{border-top:1px solid #eee5f4;padding:4px 0 18px;}.result h3{display:flex;gap:9px;align-items:center;overflow-wrap:anywhere;}.result ul{font-size:11px;color:#80698f;margin-top:9px;}.result li{display:flex;justify-content:space-between;gap:10px;padding:4px 0;}.support{font-size:11px;color:#a0647b;margin-top:8px;}footer{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:20px 0;}footer p{font-size:11px;color:#81638f;max-width:600px;}@media(max-width:767px){header{display:block;}h1{font-size:26px;}.mode-chip{display:inline-block;margin-top:12px;}.setup-grid,.session-grid{display:flex;flex-direction:column;gap:16px;}.panel,.visual-panel{width:100%;padding:18px;border-radius:18px;}.setup-grid>.visual-panel{order:1;}.setup-grid .target-wrap{max-width:210px;}.setup-grid .scale{margin:6px 0;}.setup-grid .visual-panel>.honesty{display:none;}.session-grid .target-wrap{max-width:240px;}.session-grid .visual-panel{padding:12px 16px;}.session-grid .scale{font-size:10px;gap:3px;}.session-bar{display:block;padding:16px;}.session-actions{margin-top:12px;}.session-actions button{flex:1;font-size:11px;padding:8px;}footer{align-items:flex-start;flex-direction:column;}.choices{gap:4px;}.choices button{padding:10px 5px;font-size:12px;min-height:68px;}.content-first>.panel{order:0;}.content-first>.visual-panel{order:1;}.legend{font-size:10px;}}
</style>
